import java.io.*;
import java.util.*;

public class UtkarshVariant5 {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static PrintWriter pw = new PrintWriter(System.out);
    static long MOD = 998244353L;

    public static void main(String[] args) throws IOException {
        String[] input = br.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        long k = Long.parseLong(input[1]);

        if (k >= n) {
            pw.println(0);
            pw.flush();
            return;
        }

        long[] factorials = new long[n + 1];
        long[] invFactorials = new long[n + 1];
        factorials[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorials[i] = (factorials[i - 1] * i) % MOD;
        }
        invFactorials[n] = modInverse(factorials[n], MOD);
        for (int i = n - 1; i >= 1; i--) {
            invFactorials[i] = ((i + 1) * invFactorials[i + 1]) % MOD;
        }

        if (k == 0) {
            pw.println(factorials[n]);
            pw.flush();
            return;
        }

        int r = n - (int) k;
        long sum = 0;
        int sign = 1;
        for (int i = 0; i < r; i++) {
            long comb = nCr(n, i, factorials, invFactorials);
            long val = powMod(r - i, n);
            sum = (sum + sign * comb * val) % MOD;
            sign *= -1;
        }
        long answer = (2 * nCr(n, r, factorials, invFactorials) * sum) % MOD;
        pw.println(answer);
        pw.flush();
    }

    static long nCr(int n, int r, long[] fact, long[] invFact) {
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

    static long powMod(long base, int exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static long modInverse(long a, long m) {
        return modPow(a, m - 2, m);
    }

    static long modPow(long base, int exp, long m) {
        long res = 1;
        base %= m;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % m;
            base = (base * base) % m;
            exp >>= 1;
        }
        return res;
    }
}
